const D = { energy: .62, scale: 1, speed: 1, density: .55, ornament: .6, hue: 190, x: .5, y: .5, style: 'darkfield', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// -----------------------------------------------------------------------------
// A dark-field microscopy plate of diatom frustules -- the silica glass shells
// of single-celled algae, drawn Haeckel-style. Two symmetries appear: CENTRIC
// diatoms (radial rosettes -- Arachnoidiscus, Actinoptychus, Cyclotella) and
// PENNATE diatoms (bilateral boats with a central raphe and transverse costae --
// Navicula, Pinnularia). Each specimen carries fine areolae (pits in rows),
// marginal spines and concentric annuli. They drift on bounded orbits and rotate
// on two incommensurate rates so the plate never freezes; an oblique dark-field
// illumination angle sweeps slowly, lighting one flank of every shell brighter
// than the other -- the symmetry-breaker that keeps the radial forms from reading
// identical frame to frame. Detritus of shell fragments drifts through the field.
// -----------------------------------------------------------------------------

const u = Math.min(width, height);
const sp = 0.25 + P.speed * 0.9;
const orn = 0.25 + P.ornament * 0.85;

// seeded hashes ---------------------------------------------------------------
const sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7 + 0.7) * 43758.5453; return s - Math.floor(s); };

// (re)build the specimen population on seed / density change -------------------
const nSpec = Math.round(4 + P.density * 12);
if (!S.spec || S.seedUsed !== P.seed || S.nUsed !== nSpec) {
  S.seedUsed = P.seed; S.nUsed = nSpec;
  S.spec = [];
  for (let k = 0; k < nSpec; k++) {
    const centric = fr(k * 3 + 1) < 0.62;
    const ribs = centric ? (10 + Math.floor(fr(k * 5 + 2) * 20)) : (12 + Math.floor(fr(k * 5 + 2) * 22));
    S.spec.push({
      centric,
      bx: 0.10 + fr(k * 7 + 3) * 0.80,
      by: 0.12 + fr(k * 7 + 4) * 0.76,
      rad: (centric ? 0.055 + fr(k * 11 + 5) * 0.10 : 0.05 + fr(k * 11 + 5) * 0.13),
      elong: centric ? 1 : 2.4 + fr(k * 13 + 6) * 2.6,   // pennate aspect ratio
      ribs,
      rings: 3 + Math.floor(fr(k * 17 + 7) * 4),
      rot0: fr(k * 19 + 8) * 6.2831853,
      rr1: 0.018 + fr(k * 23 + 9) * 0.05,                 // rotation rate A
      rr2: 0.011 + fr(k * 29 + 10) * 0.035,               // rotation rate B (incommensurate)
      dph1: fr(k * 31 + 11) * 6.283, dph2: fr(k * 37 + 12) * 6.283,
      dr1: 0.05 + fr(k * 41 + 13) * 0.09, dr2: 0.04 + fr(k * 43 + 14) * 0.08,
      damp: 0.012 + fr(k * 47 + 15) * 0.03,               // drift orbit amplitude (canvas frac)
      hueOff: (fr(k * 53 + 16) - 0.5) * 46,
      spine: fr(k * 59 + 17) < 0.5,
      raphe: fr(k * 61 + 18) < 0.7
    });
  }
  // detritus / marine-snow debris
  const nd = Math.round(70 + P.density * 150);
  S.deb = [];
  for (let k = 0; k < nd; k++) S.deb.push({
    x: fr(k * 3.3 + 101), y: fr(k * 5.7 + 102),
    r: 0.6 + fr(k * 7.1 + 103) * 2.4,
    p1: fr(k * 9.9 + 104) * 6.283, p2: fr(k * 11.3 + 105) * 6.283,
    s1: 0.03 + fr(k * 13.7 + 106) * 0.05, s2: 0.02 + fr(k * 15.1 + 107) * 0.045,
    br: 0.3 + fr(k * 17.9 + 108) * 0.7
  });
}

const t = K.t;
const style = P.style;
const glow = 0.4 + P.energy * 1.2 + A.rms * 0.35;
const lightAng = t * 0.12 * sp + 0.5 * Math.sin(t * 0.037) + 0.25 * Math.sin(t * 0.091 + 1.1);
const focus = 0.85 + 0.15 * Math.sin(t * 0.043) + 0.08 * Math.sin(t * 0.11 + 0.6);  // slow focus breathe

// palette per style -----------------------------------------------------------
let bgH, bgS, bgB, inkPale;
if (style === 'brightfield') { bgH = 38; bgS = 26; bgB = 60; inkPale = false; }
else if (style === 'plate') { bgH = 36; bgS = 20; bgB = 64; inkPale = false; }
else if (style === 'fluor') { bgH = 230; bgS = 58; bgB = 9; inkPale = true; }
else { bgH = 205; bgS = 52; bgB = 11; inkPale = true; }   // darkfield

push();
// ground + condenser illumination pool (breaks dead-black, lifts luminance) ---
noStroke();
rectMode(CORNER);
fill(bgH, bgS, bgB); rect(0, 0, width, height);
const cx = P.x * width, cy = P.y * height;
for (let ri = 6; ri >= 1; ri--) {
  const rr = u * (0.28 + ri * 0.12);
  if (inkPale) fill(bgH, bgS * 0.7, bgB + (7 - ri) * 3.2 * (0.7 + glow * 0.4), 30);
  else fill(bgH, bgS * 0.5, Math.min(88, bgB + (7 - ri) * 3.4), 22);
  ellipse(width * 0.5, height * 0.5, rr * 2.2, rr * 2.0);
}

// drifting detritus -----------------------------------------------------------
const dcol = inkPale ? [bgH - 10, 30, 82] : [bgH, 30, 30];
for (let k = 0; k < S.deb.length; k++) {
  const d = S.deb[k];
  const dx = (d.x + 0.02 * Math.sin(t * d.s1 * sp + d.p1)) % 1;
  const dy = (d.y + 0.02 * Math.cos(t * d.s2 * sp + d.p2)) % 1;
  const b = d.br * (0.5 + 0.5 * Math.sin(t * 0.5 + d.p1 * 3));
  if (inkPale) fill(dcol[0], dcol[1], 55 + b * 40, 30 + b * 45);
  else fill(dcol[0], dcol[1], 22 + b * 22, 30 + b * 40);
  const rr = d.r * (u / 900) * (0.6 + P.scale * 0.5);
  ellipse(dx * width, dy * height, rr, rr);
}

// specimen drawing ------------------------------------------------------------
function strokeLit(baseB, ang, hueBase, sat, wobble) {
  // dark-field: oblique light makes one flank scatter brighter -> symmetry break
  const lit = 0.45 + 0.55 * Math.max(0, Math.cos(ang - lightAng));
  let b;
  if (inkPale) b = Math.min(100, baseB * (0.35 + lit) * (0.7 + glow * 0.5));
  else b = 18 + (1 - lit) * 14;                      // dark sepia ink on pale ground
  stroke(hueBase, inkPale ? sat : sat + 18, b, wobble);
}

if (style === 'fluor') blendMode(ADD);

for (let si = 0; si < S.spec.length; si++) {
  const m = S.spec[si];
  const px = (m.bx + m.damp * Math.sin(t * m.dr1 * sp + m.dph1)) * width;
  const py = (m.by + m.damp * Math.cos(t * m.dr2 * sp + m.dph2)) * height;
  const rot = m.rot0 + m.rr1 * t * sp + 0.3 * Math.sin(m.rr2 * t * sp + m.dph1);
  const R = m.rad * u * P.scale * focus;
  if (R < 3) continue;
  const hueBase = (P.hue + m.hueOff + 360) % 360;
  const sat = inkPale ? (style === 'fluor' ? 62 : 30) : 24;

  push();
  translate(px, py);
  rotate(rot);
  noFill();

  if (m.centric) {
    // faint iridescent disc fill (scatter halo)
    if (inkPale) { noStroke(); fill(hueBase, style === 'fluor' ? 70 : 45, style === 'fluor' ? 40 : 22, 30 + glow * 12); ellipse(0, 0, R * 2, R * 2); noFill(); }
    // concentric annuli
    for (let ring = 1; ring <= m.rings; ring++) {
      const rr = R * (0.28 + ring / (m.rings + 0.6) * 0.72);
      strokeWeight(Math.max(0.5, R * 0.012));
      strokeLit(66, lightAng, hueBase, sat, 78);
      beginShape();
      for (let a = 0; a <= m.ribs; a++) {
        const th = a / m.ribs * 6.2831853;
        const wob = 1 + 0.03 * Math.sin(th * m.ribs * 0.5);
        vertex(Math.cos(th) * rr * wob, Math.sin(th) * rr * wob);
      }
      endShape();
    }
    // radial ribs, each lit by its own angle -> broken symmetry
    for (let a = 0; a < m.ribs; a++) {
      const th = a / m.ribs * 6.2831853 + rot;
      strokeWeight(Math.max(0.4, R * 0.008));
      strokeLit(70, th, hueBase, sat, 82);
      const ca = Math.cos(a / m.ribs * 6.2831853), sa = Math.sin(a / m.ribs * 6.2831853);
      line(ca * R * 0.24, sa * R * 0.24, ca * R, sa * R);
      // areolae pits along the rib
      if (orn > 0.4) {
        const np = Math.round(orn * 4);
        for (let pj = 1; pj <= np; pj++) {
          const rr = R * (0.34 + pj / (np + 1) * 0.62);
          strokeWeight(Math.max(0.6, R * 0.02));
          point(ca * rr, sa * rr);
        }
      }
    }
    // central rosette + marginal spines
    strokeWeight(Math.max(0.5, R * 0.014));
    strokeLit(80, lightAng, hueBase, sat, 90);
    ellipse(0, 0, R * 0.34, R * 0.34);
    if (m.spine) for (let a = 0; a < m.ribs; a++) {
      const th = a / m.ribs * 6.2831853;
      strokeWeight(Math.max(0.4, R * 0.006));
      strokeLit(60, th + rot, hueBase, sat, 70);
      line(Math.cos(th) * R, Math.sin(th) * R, Math.cos(th) * R * 1.14, Math.sin(th) * R * 1.14);
    }
  } else {
    // pennate: elongated lens outline, raphe, transverse costae
    const L = R * m.elong * 0.5, Wd = R * 0.5;
    if (inkPale) { noStroke(); fill(hueBase, style === 'fluor' ? 70 : 45, style === 'fluor' ? 36 : 20, 28 + glow * 10);
      beginShape(); for (let a = 0; a <= 40; a++) { const th = a / 40 * 6.2831853; const rr = 1 - 0.0; vertex(Math.cos(th) * L, Math.sin(th) * Wd * (0.6 + 0.4 * Math.abs(Math.cos(th)))); } endShape(CLOSE); noFill(); }
    strokeWeight(Math.max(0.6, R * 0.016));
    strokeLit(72, lightAng, hueBase, sat, 82);
    beginShape();
    for (let a = 0; a <= 60; a++) { const th = a / 60 * 6.2831853; vertex(Math.cos(th) * L, Math.sin(th) * Wd * (0.55 + 0.45 * Math.abs(Math.cos(th)))); }
    endShape(CLOSE);
    // raphe (central slit)
    if (m.raphe) { strokeWeight(Math.max(0.6, R * 0.02)); strokeLit(80, lightAng, hueBase, sat, 88); line(-L * 0.86, 0, L * 0.86, 0); }
    // transverse costae / striae
    const nc = Math.round(m.ribs * (0.6 + orn * 0.8));
    for (let c = 1; c < nc; c++) {
      const frac = c / nc, xx = -L + frac * 2 * L;
      const edge = Math.max(0, 1 - Math.pow(Math.abs(xx / L), 2));
      const hh = Wd * (0.35 + 0.65 * Math.sqrt(edge));
      strokeWeight(Math.max(0.4, R * 0.009));
      strokeLit(64, frac * 6.2831853 + lightAng, hueBase, sat, 74);
      line(xx, -hh, xx, hh);
    }
  }
  pop();
}
if (style === 'fluor') blendMode(BLEND);

// faint vignette to seat the plate --------------------------------------------
noFill();
for (let vi = 0; vi < 5; vi++) { stroke(bgH, bgS, inkPale ? 0 : 40, 8); strokeWeight(u * (0.05 + vi * 0.02)); ellipse(width / 2, height / 2, width * (1.02 + vi * 0.03), height * (1.02 + vi * 0.03)); }
pop();

// layer opacity for VJ compositing -- fade toward the ground colour
if (P.alpha < 100) { push(); noStroke(); rectMode(CORNER); fill(bgH, bgS, bgB, 100 - Math.max(0, Math.min(100, P.alpha))); rect(0, 0, width, height); pop(); }
blendMode(BLEND);
drawingContext.shadowBlur = 0;
